// Parse Calendly webhook payload
// Calendly sends different payload shapes for v1 and v2 webhooks
const payload = $input.item.json;

// Handle both Calendly v1 and v2 webhook formats
const event = payload.event || payload.payload?.event_type || 'invitee.created';

// v2 format
let invitee = payload.payload?.invitee || {};
let eventDetails = payload.payload?.event || {};
let questions = payload.payload?.questions_and_answers || [];

// v1 format fallback
if (!invitee.email && payload.invitee) {
  invitee = payload.invitee || {};
  eventDetails = payload.event || {};
  questions = payload.questions_and_answers || [];
}

// Extract core fields
const name = invitee.name || invitee.full_name || '';
const email = invitee.email || '';
const scheduledAt = eventDetails.start_time || invitee.scheduled_event?.start_time || '';
const endTime = eventDetails.end_time || invitee.scheduled_event?.end_time || '';
const calendlyEventId = eventDetails.uuid || payload.uri || '';
const calendlyEventUrl = eventDetails.uri || '';

// Parse intake answers
const getAnswer = (questionPart) => {
  const q = questions.find(qa => 
    (qa.question || '').toLowerCase().includes(questionPart.toLowerCase())
  );
  return q?.answer || '';
};

const igHandle = getAnswer('instagram') || getAnswer('ig handle') || '';
const dmVolume = getAnswer('dms') || getAnswer('how many') || '';
const productType = getAnswer('sell') || getAnswer('course') || '';
const heardFrom = getAnswer('hear') || '';

// Format scheduled time for display (IST)
let scheduledDisplay = scheduledAt;
try {
  const d = new Date(scheduledAt);
  scheduledDisplay = d.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'full', timeStyle: 'short' });
} catch(e) {}

// Calculate pre-call email send time (24h before)
const preCallSendTime = scheduledAt
  ? new Date(new Date(scheduledAt).getTime() - 24 * 60 * 60 * 1000).toISOString()
  : null;

// Calculate post-call reminder time (30min after end)
const postCallTime = endTime
  ? new Date(new Date(endTime).getTime() + 30 * 60 * 1000).toISOString()
  : null;

return [{
  json: {
    name,
    first_name: name.split(' ')[0] || name,
    email,
    scheduled_at: scheduledAt,
    scheduled_display: scheduledDisplay,
    end_time: endTime,
    calendly_event_id: calendlyEventId,
    calendly_event_url: calendlyEventUrl,
    ig_handle: igHandle.replace('@', '').toLowerCase(),
    dm_volume: dmVolume,
    product_type: productType,
    heard_from: heardFrom,
    pre_call_send_time: preCallSendTime,
    post_call_reminder_time: postCallTime
  }
}];

// Get lead record ID from the update response or find response
const findResp = $('Find Lead by Email').item.json;
const parsedData = $('Parse Calendly Payload').item.json;

const existingRecord = findResp.records?.[0];
const leadRecordId = existingRecord?.id || '';

return [{
  json: {
    lead_record_id: leadRecordId,
    ...parsedData
  }
}];

